    import {mapState} from "vuex";
    import theme from "@/mixins/theme";
    export default {
        name: "index.vue",
        props:{
            configObj:{
                type:Object,
                default:function () {
                    return {}
                }
            },
            configNme:{
                type:String,
                default:''
            }
        },
		mixins: [theme],
        data(){
            return {
                txtColor:'',
                activeTxtColor:'',
                bgColor:'',
				bgColor2:'',
                menuList:[],
                isSpecial:2,
				toneConfig:0,
				topConfig:0,
				bottomConfig:0,
				navStyleConfig:0,
				navConfig:0,
				prConfig:0,
				mTop:0,
				bgRadius:0
            }
        },
        computed: {
            ...mapState('admin/mobildConfig', ['pageFooter'])
        },
        watch:{
            'pageFooter': {
                handler (nVal, oVal) {
                    this.setConfig(nVal);
                },
                deep: true
            }
        },
        mounted() {
            let data = this.$store.state.admin.mobildConfig.pageFooter
            this.setConfig(data)
        },
        methods:{
            setConfig (data) {
                this.txtColor = data.txtColor.color[0].item;
                this.activeTxtColor = data.activeTxtColor.color[0].item;
                this.bgColor = data.bgColor.color[0].item;
				this.bgColor2 = data.bgColor2.color[0].item;
				this.navStyleConfig = data.navStyleConfig.tabVal;
				this.toneConfig = data.toneConfig.tabVal;
				this.navConfig = data.navConfig.tabVal;
				this.topConfig = data.topConfig.val;
				this.bottomConfig = data.bottomConfig.val;
				this.prConfig = data.prConfig.val;
				this.mTop = data.mbConfig.val
				let fillet = data.fillet.type;
				let filletVal = data.fillet.val;
				let valList = data.fillet.valList;
				this.bgRadius = fillet? valList[0].val+ 'px ' +valList[1].val + 'px ' + valList[3].val + 'px ' + valList[2].val +'px' : filletVal +'px';
				this.$store.commit("admin/mobildConfig/footType", this.navConfig);
				this.$store.commit("admin/mobildConfig/footBottom", this.mTop);
                this.menuList = []
                this.$set(this,'menuList',data.menuList)
                if(data.status.title == '是否显示'){
                    this.isSpecial = 2
                }else {
                    this.isSpecial = 0
                }
            }
        }
    }
